<style>
:root{--green:#2f6b3f;--dark:#1f4d2e;--cream:#f8f6ed;--line:#dfe5dc;--ink:#1f2d22;--soft:#edf4e9}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f8f6ed,#edf5e9);color:var(--ink);font:14px Arial,sans-serif}header{background:linear-gradient(115deg,#1f4d2e,#36764a);color:#fff;padding:20px 5%;display:flex;justify-content:space-between;align-items:center;gap:24px;box-shadow:0 4px 18px #1f4d2e33}header h1{margin:0;font-size:24px;letter-spacing:.2px}header h1 small{display:block;margin-top:3px;font-size:11px;font-weight:400;opacity:.78}header a,header button{color:#fff;background:transparent;border:0;cursor:pointer;text-decoration:none;font:inherit}header a:hover,header button:hover{opacity:.75}main{width:min(1250px,92%);margin:28px auto}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;gap:12px}.toolbar h2{margin:0;color:var(--dark)}.toolbar-actions,.filter{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.refresh,.filter button{border:1px solid var(--green);background:#fff;color:var(--green);border-radius:7px;padding:9px 13px;cursor:pointer}.filter{padding:12px;margin-bottom:14px;background:#fff;border:1px solid var(--line);border-radius:10px}.filter label{font-size:12px;font-weight:700;color:var(--dark)}.filter input{margin-left:5px;padding:8px;border:1px solid var(--line);border-radius:6px;font:inherit}.table-wrap{overflow:auto;background:#fff;border:1px solid var(--line);border-radius:10px;box-shadow:0 10px 24px #2f6b3f0d}table{width:100%;border-collapse:collapse;min-width:950px}th,td{padding:13px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;font-size:13px}th{background:var(--soft);color:var(--dark)}tr.order-new{background:#fff9df;outline:2px solid #d9a441;outline-offset:-2px}select,textarea{width:100%;border:1px solid var(--line);border-radius:6px;padding:7px;font:inherit}textarea{min-width:150px;margin-top:6px}.save{margin-top:6px;padding:7px 10px;color:#fff;background:var(--green);border:0;border-radius:6px;cursor:pointer}.save:disabled{opacity:.65;cursor:wait}.message{min-height:20px;color:#a33}.toast{position:fixed;right:22px;bottom:22px;z-index:40;max-width:360px;padding:13px 16px;border-radius:9px;background:#1f4d2e;color:#fff;box-shadow:0 10px 30px #1f2d2240;transform:translateY(20px);opacity:0;pointer-events:none;transition:.2s}.toast.show{transform:translateY(0);opacity:1}.toast.error{background:#a33}.new-order-alert{display:none;width:100%;margin:0 0 16px;padding:13px 16px;border:1px solid #d9a441;border-radius:9px;background:#fff4c9;color:#654b13;text-align:left;font-weight:700;cursor:pointer}.new-order-alert.show{display:block}.modal-backdrop{position:fixed;inset:0;background:#17271c99;display:none;align-items:center;justify-content:center;padding:20px;z-index:20}.modal-backdrop.show{display:flex}.modal{width:min(760px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:12px;padding:22px}.modal label{display:grid;gap:5px;margin:10px 0;font-weight:700}.modal input,.modal textarea{padding:9px}.modal h2{margin-top:0;color:var(--dark)}@media(max-width:650px){header{align-items:flex-start;flex-direction:column;padding:18px 5%}header>div{justify-content:flex-start;width:100%;line-height:1.8}.toolbar{align-items:flex-start;flex-direction:column}.filter{align-items:flex-start;flex-direction:column}.filter input{margin:4px 0 0}}
