<body>
<header><h1>Dashboard Admin<small>Kelola pesanan dan toko Mushroom Organik</small></h1><div><span><?= htmlspecialchars($user['name'], ENT_QUOTES, 'UTF-8') ?></span><a href="products.php">Kelola produk</a><a href="../index.php">Toko</a><button id="logout">Keluar</button></div></header>
<main><div class="toolbar"><h2>Pesanan pelanggan</h2><div class="toolbar-actions"><button class="refresh" id="refresh">Muat ulang</button><button class="refresh" id="editAbout">Edit profil toko</button></div></div><button class="new-order-alert" id="newOrderAlert" type="button"></button><div class="filter"><label>Dari tanggal<input type="date" id="dateFrom"></label><label>Sampai tanggal<input type="date" id="dateTo"></label><button class="refresh" id="applyFilter" type="button">Terapkan filter</button><button class="refresh" id="clearFilter" type="button">Reset</button></div><p class="message" id="message"></p><div class="table-wrap"><table><thead><tr><th>Order</th><th>Pelanggan</th><th>Total</th><th>Status pembayaran</th><th>Status pesanan</th><th>Aksi</th></tr></thead><tbody id="orders"><tr><td colspan="6">Memuat data...</td></tr></tbody></table></div></main>
<div class="toast" id="toast" role="status"></div>
<div class="modal-backdrop" id="aboutBackdrop"><section class="modal" role="dialog" aria-modal="true"><h2>Profil toko yang tampil di Tentang Kami</h2><p>Perubahan langsung tampil di halaman toko.</p><form id="aboutForm"><label>Judul<input name="about_title" maxlength="160"></label><label>Deskripsi utama<textarea name="about_description" maxlength="3000"></textarea></label><label>Judul kartu profil<input name="about_badge_title" maxlength="160"></label><label>Isi kartu profil<textarea name="about_badge_text" maxlength="3000"></textarea></label><label>WhatsApp<input name="contact_whatsapp" maxlength="40"></label><label>Email<input name="contact_email" maxlength="190"></label><label>Instagram<input name="contact_instagram" maxlength="120"></label><p class="message" id="aboutMessage"></p><button class="save">Simpan profil</button> <button type="button" class="refresh" id="closeAbout">Batal</button></form></section></div>
<script>
const csrfToken=<?= json_encode($csrfToken) ?>;
const statuses=['Menunggu pembayaran','Sedang dikemas','Telah dikirim','Sudah sampai','Dibatalkan'];
const paymentStatuses=['Menunggu verifikasi pembayaran','Pembayaran disetujui','Pembayaran ditolak'];
const orders=document.getElementById('orders'),message=document.getElementById('message'),toast=document.getElementById('toast'),aboutBackdrop=document.getElementById('aboutBackdrop'),aboutForm=document.getElementById('aboutForm'),newOrderAlert=document.getElementById('newOrderAlert');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
let toastTimer;
function showToast(text,error=false){toast.textContent=text;toast.classList.toggle('error',error);toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),3200);}
function filterQuery(){const params=new URLSearchParams();const from=document.getElementById('dateFrom').value;const to=document.getElementById('dateTo').value;if(from)params.set('date_from',from);if(to)params.set('date_to',to);return params.toString()?('?'+params.toString()):'';}
function orderRow(order){return `<tr id="order-${esc(order.id)}" data-order-id="${esc(order.id)}"><td><strong>${esc(order.id)}</strong><br><small>${esc(order.created_at)}</small></td><td>${esc(order.customer_name)}<br>${esc(order.customer_phone)}<br><small>${esc(order.email||'')}</small></td><td>Rp${Number(order.total).toLocaleString('id-ID')}</td><td><select data-payment="${esc(order.id)}">${paymentStatuses.map(status=>`<option ${status===order.payment_status?'selected':''}>${esc(status)}</option>`).join('')}</select>${order.proof_file?`<a class="proof" href="../${esc(order.proof_file)}" target="_blank" rel="noopener">Lihat bukti pembayaran</a>`:''}</td><td><select data-status="${esc(order.id)}">${statuses.map(status=>`<option ${status===order.order_status?'selected':''}>${esc(status)}</option>`).join('')}</select><textarea data-note="${esc(order.id)}" placeholder="Catatan admin">${esc(order.admin_note||'')}</textarea></td><td><button class="save" data-save="${esc(order.id)}">Simpan</button></td></tr>`;}
async function loadOrders(clearMessage=true){if(clearMessage)message.textContent='';const response=await fetch('../api/admin.php'+filterQuery());const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Data gagal dimuat.');orders.innerHTML=result.orders.length?result.orders.map(orderRow).join(''):'<tr><td colspan="6">Belum ada pesanan pada tanggal tersebut.</td></tr>';return result.orders;}
async function checkNewOrders(){try{const response=await fetch('../api/admin.php');const result=await response.json();if(!response.ok||!result.success||!result.orders.length)return;const newest=result.orders[0];const seen=localStorage.getItem('adminLastOrderId');if(!seen){localStorage.setItem('adminLastOrderId',newest.id);return;}if(seen!==newest.id){newOrderAlert.textContent='Pesanan baru masuk: '+newest.id+' dari '+newest.customer_name+'. Klik untuk melihat.';newOrderAlert.dataset.orderId=newest.id;newOrderAlert.classList.add('show');showToast('Ada pesanan baru dari '+newest.customer_name+'.');localStorage.setItem('adminLastOrderId',newest.id);}}catch(error){console.warn(error);}}
newOrderAlert.addEventListener('click',async()=>{const orderId=newOrderAlert.dataset.orderId;document.getElementById('dateFrom').value='';document.getElementById('dateTo').value='';newOrderAlert.classList.remove('show');await loadOrders(false);const row=document.getElementById('order-'+orderId);if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.classList.add('order-new');setTimeout(()=>row.classList.remove('order-new'),5000);}});
orders.addEventListener('click',async event=>{const button=event.target.closest('[data-save]');if(!button)return;const orderId=button.dataset.save;const status=document.querySelector(`[data-status="${CSS.escape(orderId)}"]`).value;const paymentStatus=document.querySelector(`[data-payment="${CSS.escape(orderId)}"]`).value;const note=document.querySelector(`[data-note="${CSS.escape(orderId)}"]`).value;button.disabled=true;button.textContent='Menyimpan...';try{const response=await fetch('../api/admin.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({orderId,status,paymentStatus,note})});const result=await response.json();if(!response.ok||!result.success)throw new Error(result.message||'Status gagal disimpan.');showToast('Status pembayaran dan pesanan berhasil diperbarui.');await loadOrders(false);}catch(error){showToast(error.message,true);}finally{button.disabled=false;button.textContent='Simpan';}});
document.getElementById('applyFilter').addEventListener('click',()=>loadOrders().catch(error=>showToast(error.message,true)));document.getElementById('clearFilter').addEventListener('click',()=>{document.getElementById('dateFrom').value='';document.getElementById('dateTo').value='';loadOrders().catch(error=>showToast(error.message,true));});document.getElementById('refresh').addEventListener('click',()=>loadOrders().catch(error=>showToast(error.message,true)));
document.getElementById('logout').addEventListener('click',async()=>{await fetch('../api/auth.php?action=logout',{method:'POST',headers:{'X-CSRF-Token':csrfToken}});window.location.href='../auth.php';});loadOrders().catch(error=>showToast(error.message,true));checkNewOrders();setInterval(checkNewOrders,30000);
</script>
<script>document.getElementById('editAbout')?.remove();document.getElementById('aboutBackdrop')?.remove();</script>
</body>
